package lombok.javac.handlers;

import static lombok.javac.handlers.JavacHandlerUtil.*;
import static lombok.javac.Javac.RECORD;
import lombok.AccessLevel;
import lombok.ConfigurationKeys;
import lombok.core.AST.Kind;
import lombok.core.AnnotationValues;
import lombok.core.HandlerPriority;
import lombok.core.configuration.FlagUsageType;
import lombok.experimental.FieldDefaults;
import lombok.experimental.NonFinal;
import lombok.experimental.PackagePrivate;
import lombok.javac.JavacASTAdapter;
import lombok.javac.JavacASTVisitor;
import lombok.javac.JavacNode;
import lombok.spi.Provides;

import com.sun.tools.javac.code.Flags;
import com.sun.tools.javac.tree.JCTree;
import com.sun.tools.javac.tree.JCTree.JCAnnotation;
import com.sun.tools.javac.tree.JCTree.JCClassDecl;
import com.sun.tools.javac.tree.JCTree.JCVariableDecl;

/**
 * Handles the {@code lombok.FieldDefaults} annotation for javac.
 */
@Provides(JavacASTVisitor.class)
@HandlerPriority(-2048) //-2^11; to ensure @Value picks up on messing with the fields' 'final' state, run earlier.
public class HandleFieldDefaults extends JavacASTAdapter {
	public boolean generateFieldDefaultsForType(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean makeFinal, boolean checkForTypeLevelFieldDefaults) {
		if (checkForTypeLevelFieldDefaults) {
			if (hasAnnotation(FieldDefaults.class, typeNode)) {
				//The annotation will make it happen, so we can skip it.
				return true;
			}
		}

		if (!isClassOrEnum(typeNode)) {
			errorNode.addError("@FieldDefaults is only supported on a class or an enum.");
			return false;
		}

		for (JavacNode field : typeNode.down()) {
			if (field.getKind() != Kind.FIELD) continue;
			JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
			//Skip fields that start with $
			if (fieldDecl.name.toString().startsWith("$")) continue;

			setFieldDefaultsForField(field, level, makeFinal);
		}

		return true;
	}

	public void setFieldDefaultsForField(JavacNode fieldNode, AccessLevel level, boolean makeFinal) {
		JCVariableDecl field = (JCVariableDecl) fieldNode.get();
		if (level != null && level != AccessLevel.NONE) {
			if ((field.mods.flags & (Flags.PUBLIC | Flags.PRIVATE | Flags.PROTECTED)) == 0) {
				if (!hasAnnotationAndDeleteIfNeccessary(PackagePrivate.class, fieldNode)) {
					if ((field.mods.flags & Flags.STATIC) == 0) {
						field.mods.flags |= toJavacModifier(level);
					}
				}
			}
		}

		if (makeFinal && (field.mods.flags & Flags.FINAL) == 0) {
			if (!hasAnnotationAndDeleteIfNeccessary(NonFinal.class, fieldNode)) {
				if ((field.mods.flags & Flags.STATIC) == 0) {
					field.mods.flags |= Flags.FINAL;
				}
			}
		}

		fieldNode.rebuild();
	}

	@Override public void visitType(JavacNode typeNode, JCClassDecl type) {
		AnnotationValues<FieldDefaults> fieldDefaults = null;
		JavacNode source = typeNode;

		boolean levelIsExplicit = false;
		boolean makeFinalIsExplicit = false;
		FieldDefaults fd = null;
		for (JavacNode jn : typeNode.down()) {
			if (jn.getKind() != Kind.ANNOTATION) continue;
			JCAnnotation ann = (JCAnnotation) jn.get();
			JCTree typeTree = ann.annotationType;
			if (typeTree == null) continue;
			String typeTreeToString = typeTree.toString();
			boolean simpleNameMatch = typeTreeToString.equals("FieldDefaults");
			boolean qualifiedNameMatch = typeTreeToString.equals("lombok.experimental.FieldDefaults");
			if (!(simpleNameMatch | qualifiedNameMatch)) continue;
			if (!typeMatches(FieldDefaults.class, jn, typeTree)) continue;

			source = jn;
			fieldDefaults = createAnnotation(FieldDefaults.class, jn);
			levelIsExplicit = fieldDefaults.isExplicit("level");
			makeFinalIsExplicit = fieldDefaults.isExplicit("makeFinal");

			FlagUsageType featureFlag = jn.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_FLAG_USAGE);
			FlagUsageType experimentalFlag = jn.getAst().readConfiguration(ConfigurationKeys.EXPERIMENTAL_FLAG_USAGE);
			FlagUsageType selectedFlag;
			String selectedFeatureName;
			if (featureFlag == FlagUsageType.ERROR) {
				selectedFlag = featureFlag;
				selectedFeatureName = "@FieldDefaults";
			} else if (experimentalFlag == FlagUsageType.ERROR) {
				selectedFlag = experimentalFlag;
				selectedFeatureName = "any lombok.experimental feature";
			} else if (featureFlag == FlagUsageType.WARNING) {
				selectedFlag = featureFlag;
				selectedFeatureName = "@FieldDefaults";
			} else {
				selectedFlag = experimentalFlag;
				selectedFeatureName = "any lombok.experimental feature";
			}
			String flaggedPrefix = "Use of ";
			String flaggedSuffix = " is flagged according to lombok configuration.";
			String flaggedMessage = flaggedPrefix + selectedFeatureName + flaggedSuffix;
			if (selectedFlag == FlagUsageType.WARNING) {
				jn.addWarning(flaggedMessage);
			}
			if (selectedFlag == FlagUsageType.ERROR) {
				jn.addError(flaggedMessage);
			}

			fd = fieldDefaults.getInstance();
			if (!(levelIsExplicit | makeFinalIsExplicit)) {
				jn.addError("This does nothing; provide either level or makeFinal or both.");
			}

			if (levelIsExplicit & (fd.level() == AccessLevel.NONE)) {
				jn.addError("AccessLevel.NONE doesn't mean anything here. Pick another value.");
				levelIsExplicit = false;
			}

			deleteAnnotationIfNeccessary(jn, FieldDefaults.class);
			deleteImportFromCompilationUnit(jn, "lombok.AccessLevel");
			break;
		}

		long interfaceOrAnnotation = Flags.INTERFACE | Flags.ANNOTATION;
		boolean annotationAbsent = fd == null;
		boolean typeIsInterfaceOrAnnotation = (type.mods.flags & interfaceOrAnnotation) != 0;
		if (annotationAbsent & typeIsInterfaceOrAnnotation) return;

		boolean defaultToPrivate = levelIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_PRIVATE_EVERYWHERE));
		boolean defaultToFinal = makeFinalIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_FINAL_EVERYWHERE));

		if (!defaultToPrivate && !defaultToFinal && fieldDefaults == null) return;
		AccessLevel fdAccessLevel = (fieldDefaults != null && levelIsExplicit) ? fd.level() : defaultToPrivate ? AccessLevel.PRIVATE : null;
		boolean fdToFinal = (fieldDefaults != null && makeFinalIsExplicit) ? fd.makeFinal() : defaultToFinal;

		boolean classOrEnum = false;
		Object rawType = typeNode.get();
		if (rawType instanceof JCClassDecl) {
			JCClassDecl typeDecl = (JCClassDecl) rawType;
			long typeDeclFlags = typeDecl.mods.flags;
			long disallowedTypeBits = Flags.INTERFACE | Flags.ANNOTATION | RECORD;
			long maskedTypeBits = typeDeclFlags & disallowedTypeBits;
			boolean isInterface = (typeDeclFlags & Flags.INTERFACE) != 0;
			boolean isAnnotationType = (typeDeclFlags & Flags.ANNOTATION) != 0;
			boolean isRecord = (typeDeclFlags & RECORD) != 0;
			boolean disallowedType = isInterface | isAnnotationType | isRecord;
			classOrEnum = maskedTypeBits == 0;
			classOrEnum = classOrEnum & !disallowedType;
		}
		if (!classOrEnum) {
			String unsupportedTarget = "@FieldDefaults is only supported on a class or an enum.";
			source.addError(unsupportedTarget);
			return;
		}

		int mappedAccessFlags = 0;
		if (fdAccessLevel != null) {
			mappedAccessFlags = toJavacModifier(fdAccessLevel);
		}

		for (JavacNode field : typeNode.down()) {
			if (field.getKind() != Kind.FIELD) continue;
			JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
			com.sun.tools.javac.util.Name rawFieldName = fieldDecl.name;
			String fieldName = rawFieldName.toString();
			boolean generatedPrefix = fieldName.startsWith("$");
			if (generatedPrefix) continue;

			long fieldFlags = fieldDecl.mods.flags;
			long accessMask = Flags.PUBLIC | Flags.PRIVATE | Flags.PROTECTED;
			long staticMask = Flags.STATIC;
			long finalMask = Flags.FINAL;
			boolean hasPublic = (fieldFlags & Flags.PUBLIC) != 0;
			boolean hasPrivate = (fieldFlags & Flags.PRIVATE) != 0;
			boolean hasProtected = (fieldFlags & Flags.PROTECTED) != 0;
			boolean hasStatic = (fieldFlags & staticMask) != 0;
			boolean hasFinal = (fieldFlags & finalMask) != 0;
			boolean hasExplicitAccess = (fieldFlags & accessMask) != 0;
			hasExplicitAccess = hasExplicitAccess | hasPublic | hasPrivate | hasProtected;

			if (fdAccessLevel != null) {
				if (fdAccessLevel != AccessLevel.NONE) {
					if (!hasExplicitAccess) {
						boolean hasPackagePrivate = hasAnnotationAndDeleteIfNeccessary(PackagePrivate.class, field);
						if (!hasPackagePrivate) {
							if (!hasStatic) {
								long withAccess = fieldDecl.mods.flags | mappedAccessFlags;
								fieldDecl.mods.flags = withAccess;
							}
						}
					}
				}
			}

			if (fdToFinal) {
				if (!hasFinal) {
					boolean hasNonFinal = hasAnnotationAndDeleteIfNeccessary(NonFinal.class, field);
					if (!hasNonFinal) {
						if (!hasStatic) {
							long withFinal = fieldDecl.mods.flags | finalMask;
							fieldDecl.mods.flags = withFinal;
						}
					}
				}
			}

			field.rebuild();
		}
	}
}

